// Share-card URLs, and the image an entity route unfurls with.
//
// There is no renderer at request time. Cards are PNGs generated by
// `npm run og:fallbacks` and committed to `public/og/`, so an og:image is a
// plain static asset: nothing to time out, nothing to fall back from. An
// earlier build rendered them on demand at `/api/og/<kind>/<id>.png` and that
// is exactly what went wrong — Workers Free allows 10ms CPU per request and a
// satori + resvg pass costs ~400ms, so production returned 1102 and the tag
// resolved to nothing. See docs/og-cards.md.

// The committed card for a section. Every route's og:image is one of these,
// unless the route is an entity that carries its own photo.
export const ogStaticUrl = (slug, siteUrl = "") => `${siteUrl}/og/${slug}.png`;

// Which committed card each entity kind falls back to when the row has no
// photo of its own — which, for books, blogs, decks, tags and shares, is
// always. `src/data/routeManifest.test.js` asserts every slug here is a real
// committed PNG, so a new detail route cannot ship pointing at nothing.
export const CARD_FALLBACKS = {
  book: "books",
  blog: "100-days-to-offload",
  sport: "sports",
  trek: "treks",
  project: "projects",
  presentation: "presentations",
  microblog: "micro-blog",
  tag: "tags",
  "ask-share": "ask-share",
};

// True for our own cards, which are all exactly 1200x630. Both meta layers use
// this to decide whether to DECLARE og:image:width/height: an entity's own
// photo is whatever shape the camera was, and asserting 1200x630 over a 900px
// portrait makes every platform crop it wrong. Undeclared, they measure it.
export const isCardImage = (url) => /\/og\/[^/]+\.png$/.test(String(url || ""));

// Re-hosts a card URL onto the origin actually serving the page.
//
// `src/data/pageMeta.js` has to hard-code SITE_URL, because it is import-free
// and has no way to know the host. That made every Cloudflare Pages PREVIEW
// advertise `https://sankettambare.in/og/<slug>.png` — a card that only exists
// once the branch is in production. Until then that path falls through to the
// SPA, which answers `200 text/html`, so a scraper fetches an HTML page where
// an image should be and shows nothing at all. A preview could never show its
// own cards, which is exactly when you want to check them.
//
// Only OUR cards are moved. A row's photo is an absolute Supabase URL that is
// already correct everywhere, and the canonical/og:url stay on SITE_URL so a
// preview never advertises itself as the canonical home of a page.
export function cardUrlForOrigin(imageUrl, origin, siteUrl) {
  if (!origin || !siteUrl || origin === siteUrl) return imageUrl;
  if (!isCardImage(imageUrl)) return imageUrl;
  return String(imageUrl).replace(siteUrl, origin);
}

// Resolves a stored image path to a public URL. PostgREST rows hold RELATIVE
// paths for anything uploaded through /admin (see toStorageUrl in
// src/lib/supabaseClient.js, which does the same job on the client but cannot
// be reused here because it imports the supabase-js client). Absolute URLs pass
// through untouched, which is what makes this safe to call on a client row that
// `toStorageImages` has already absolutised — hence the `supabaseUrl` default.
export function storageUrl(value, supabaseUrl = "") {
  if (!value) return null;
  const path = String(value);
  if (/^https?:\/\//i.test(path)) return path;
  const clean = path.startsWith("/") ? path : `/${path}`;
  return `${supabaseUrl}/storage/v1/object/public/media${clean}`;
}

// First usable image out of a `slide_images` column, which holds either bare
// URL strings or `{ url }` objects depending on when the row was written.
export function firstSlideImage(slideImages, supabaseUrl = "") {
  if (!Array.isArray(slideImages)) return null;
  const found = slideImages.find((entry) => (typeof entry === "string" ? entry : entry && entry.url));
  if (!found) return null;
  return storageUrl(typeof found === "string" ? found : found.url, supabaseUrl);
}

export default ogStaticUrl;
